// ============================================================
// BIESTATMUNG
// Liest [Biestatmung]Technikname|Beschreibung[/Biestatmung]
// (vom Forum bereits zu <div class="biestatmung">...</div>
// umgewandelt) und baut daraus die komplette Struktur.
// 5 Krallenbild-Ausschnitte (Vecteezy, Attribution noetig) sind
// hier als Base64 eingebettet.
// ============================================================

var BS_CLAW_SINGLE     = "data:image/png;base64,";
var BS_CLAW_TOPMID     = "data:image/png;base64,";
var BS_CLAW_BOTRIGHT   = "data:image/png;base64,";
var BS_CLAW_HORIZONTAL = "data:image/png;base64,";
var BS_CLAW_BOTLEFT    = "data:image/png;base64,";

document.querySelectorAll(".biestatmung").forEach(function (el) {
  if (el.dataset.bsInit) return;
  el.dataset.bsInit = "1";

  var raw = el.textContent.trim();
  var parts = raw.split("|");
  var technikname = (parts[0] || "").trim();
  var beschreibung = (parts.slice(1).join("|") || "").trim();

  var claws =
    '<img class="bs-claw" src="' + BS_CLAW_SINGLE + '" alt="" ' +
      'style="top:50%; left:40px; height:220px; transform:translateY(-50%); opacity:.55; animation-delay:0s;">' +
    '<img class="bs-claw" src="' + BS_CLAW_TOPMID + '" alt="" ' +
      'style="top:-30px; right:260px; height:140px; transform:rotate(-8deg); opacity:.4; animation-delay:.5s;">' +
    '<img class="bs-claw" src="' + BS_CLAW_BOTRIGHT + '" alt="" ' +
      'style="bottom:-40px; right:30px; height:170px; transform:rotate(-4deg); opacity:.45; animation-delay:1s;">' +
    '<img class="bs-claw" src="' + BS_CLAW_HORIZONTAL + '" alt="" ' +
      'style="top:15px; right:20px; height:90px; transform:rotate(3deg); opacity:.35; animation-delay:1.5s;">' +
    '<img class="bs-claw" src="' + BS_CLAW_BOTLEFT + '" alt="" ' +
      'style="bottom:-50px; left:10px; height:150px; transform:rotate(10deg) scaleX(-1); opacity:.3; animation-delay:2s;">';

  var dustSpecs = [
    { top:'18%', left:'65%', size:2, color:'#ffb870', glow:'#ff8030', delay:'.4s' },
    { top:'75%', left:'58%', size:3, color:'#c9a860', glow:'#a87830', delay:'1.3s' },
    { top:'55%', left:'72%', size:2, color:'#ff8030', glow:'#ff5010', delay:'2.1s' },
    { top:'30%', left:'85%', size:3, color:'#c9a860', glow:'#a87830', delay:'2.8s' },
    { top:'85%', left:'40%', size:2, color:'#ffb870', glow:'#ff8030', delay:'.9s' },
    { top:'10%', left:'8%',  size:3, color:'#ff8030', glow:'#ff5010', delay:'1.8s' },
    { top:'65%', left:'12%', size:2, color:'#c9a860', glow:'#a87830', delay:'2.5s' }
  ];
  var dust = dustSpecs.map(function (d) {
    return '<div class="bs-dust" style="width:' + d.size + 'px;height:' + d.size + 'px;' +
      'background:' + d.color + ';box-shadow:0 0 5px ' + d.glow + ';' +
      'top:' + d.top + ';left:' + d.left + ';animation-delay:' + d.delay + ';"></div>';
  }).join('');

  el.innerHTML =
    '<div class="bs-grain"></div>' +
    '<div class="bs-vignette"></div>' +
    claws + dust +
    '<div class="bs-content">' +
      '<div class="bs-label">Biestatmung</div>' +
      '<div class="bs-title"><span class="bs-typewriter"></span></div>' +
      '<div class="bs-divider"></div>' +
      '<div class="bs-desc"></div>' +
    '</div>';

  var titleEl = el.querySelector('.bs-typewriter');
  var descEl = el.querySelector('.bs-desc');
  descEl.textContent = beschreibung;

  var i = 0;
  function type() {
    if (i <= technikname.length) {
      titleEl.textContent = technikname.slice(0, i);
      i++;
      setTimeout(type, 90);
    }
  }
  setTimeout(type, 800);
});
